# Created: 2026-07-02

#!/usr/bin/env python3
"""
Academic Writer — Style Metrics Extractor (CLI)

Reads a corpus of past-articles and emits the `computationalMetrics` shape
consumed by src/skills/write/references/style-fingerprint-rubric.md, plus a
`frequentTerms` field (the researcher's high-frequency content vocabulary)
consumed by the write skill's vocabulary steering.

Usage (matches the calling convention used by src/skills/init/SKILL.md):

    python3 extract-style-metrics.py \\
      --input past-articles/ \\
      --aggregate \\
      --baseline .ctx/hebrew-linguistic-reference.md \\
      --contrastive \\
      --json \\
      --output /tmp/style-metrics.json

Output JSON shape:

    {
      "computationalMetrics": {
        "sentenceLevel": {"length": {...}, "distribution": {...},
                           "passiveVoiceFrequency": ..., "firstPersonFrequency": ...},
        "paragraphStructure": {"length": {...}, "sentencesPerParagraph": {...}},
        "transitions": {"frequencyPerParagraph": ..., "byCategory": {...}},
        "vocabulary": {"typeTokenRatio": ..., "avgWordLength": ...}
      },
      "frequentTerms": [{"term": ..., "count": ..., "frequency": ...}, ...],
      "contrastive": {...},   // only present with --contrastive + --baseline
      "meta": {"filesProcessed": [...], "totalWords": ..., "totalSentences": ...,
               "warnings": [...]}
    }

--aggregate merges every file in --input into one corpus before computing
metrics (the mode used by the init skill's style-fingerprint step). Without
--aggregate, metrics are computed per file and returned under "files".

No third-party dependencies — Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Optional

sys.path.insert(0, str(Path(__file__).resolve().parent / "lib"))

from style_contrastive import compute_contrastive, extract_baseline_json  # noqa: E402
from style_frequent_terms import (  # noqa: E402
    compute_frequent_terms,
    find_structural_furniture_terms,
)
from style_metrics_core import (  # noqa: E402
    compute_computational_metrics,
    split_sentences,
    tokenize_words,
)
from style_text_extraction import read_corpus  # noqa: E402

DEFAULT_TOP_FREQUENT_TERMS = 30
DEFAULT_MIN_TERM_LENGTH = 2
DEFAULT_FURNITURE_MAX_WORDS = 10
DEFAULT_FURNITURE_SHARE = 0.8
DEFAULT_FURNITURE_MIN_COUNT = 5
DEFAULT_FURNITURE_CANDIDATE_MULTIPLIER = 3


def _load_style_metrics_config(script_dir: Path) -> dict:
    candidates = [script_dir.parent / "thresholds.json", script_dir / "thresholds.json"]
    for candidate in candidates:
        try:
            data = json.loads(candidate.read_text(encoding="utf-8"))
            return data.get("typography", {}).get("styleMetrics", {})
        except (OSError, json.JSONDecodeError, AttributeError):
            continue
    return {}


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Extract computational style metrics from a corpus of past articles."
    )
    parser.add_argument(
        "--input", required=True, help="File or directory of past-articles to analyze."
    )
    parser.add_argument(
        "--aggregate",
        action="store_true",
        help="Merge all corpus files into one combined fingerprint (default caller mode).",
    )
    parser.add_argument(
        "--baseline",
        default=None,
        help="Path to the cached Hebrew Linguistic Reference markdown (for --contrastive).",
    )
    parser.add_argument(
        "--contrastive",
        action="store_true",
        help="Emit a 'contrastive' section comparing metrics against --baseline.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Emit JSON (currently the only supported format).",
    )
    parser.add_argument(
        "--output", default=None, help="Write JSON to this file instead of stdout."
    )
    parser.add_argument(
        "--top-terms",
        type=int,
        default=None,
        help="Override frequentTerms count (default: thresholds.json > typography.styleMetrics.topFrequentTermsCount, else 30).",
    )
    return parser


def _metrics_for_text(text: str) -> dict:
    return compute_computational_metrics(text)


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    script_dir = Path(__file__).resolve().parent
    config = _load_style_metrics_config(script_dir)
    top_n = args.top_terms or config.get(
        "topFrequentTermsCount", DEFAULT_TOP_FREQUENT_TERMS
    )
    min_len = config.get("minTermLength", DEFAULT_MIN_TERM_LENGTH)
    furn_max_words = config.get("furnitureMaxWords", DEFAULT_FURNITURE_MAX_WORDS)
    furn_share = config.get("furnitureShare", DEFAULT_FURNITURE_SHARE)
    furn_min_count = config.get("furnitureMinCount", DEFAULT_FURNITURE_MIN_COUNT)
    furn_multiplier = config.get(
        "furnitureCandidateMultiplier", DEFAULT_FURNITURE_CANDIDATE_MULTIPLIER
    )

    input_path = Path(args.input)
    texts, warnings = read_corpus(input_path)

    if not texts:
        result = {
            "computationalMetrics": None,
            "frequentTerms": [],
            "meta": {
                "filesProcessed": [],
                "totalWords": 0,
                "totalSentences": 0,
                "warnings": warnings
                + [f"No readable corpus files found under {input_path}"],
            },
        }
        _emit(result, args.output)
        return 0

    if args.aggregate:
        documents = list(texts.values())
        combined_text = "\n\n".join(documents)
        metrics = _metrics_for_text(combined_text)
        # Structural furniture is a PARAGRAPH-LEVEL signal (ToC lines and
        # section headers are short paragraphs), so it is invisible once the
        # corpus is concatenated — pass the documents, not just combined_text.
        dropped = sorted(
            find_structural_furniture_terms(
                documents,
                min_len,
                furn_max_words,
                furn_share,
                furn_min_count,
                top_n,
                furn_multiplier,
            )
        )
        result = {
            "computationalMetrics": metrics,
            "frequentTerms": compute_frequent_terms(
                combined_text,
                top_n,
                min_len,
                documents=documents,
                furniture_max_words=furn_max_words,
                furniture_share=furn_share,
                furniture_min_count=furn_min_count,
                furniture_candidate_multiplier=furn_multiplier,
            ),
            "meta": {
                "filesProcessed": sorted(texts.keys()),
                "totalWords": len(tokenize_words(combined_text)),
                "totalSentences": len(split_sentences(combined_text)),
                "droppedFurnitureTerms": dropped,
                "warnings": warnings,
            },
        }
    else:
        per_file = {}
        for name, text in texts.items():
            per_file[name] = {
                "computationalMetrics": _metrics_for_text(text),
                "frequentTerms": compute_frequent_terms(text, top_n, min_len),
            }
        result = {
            "files": per_file,
            "meta": {
                "filesProcessed": sorted(texts.keys()),
                "warnings": warnings,
            },
        }

    if args.contrastive:
        if not args.baseline:
            result.setdefault("meta", {}).setdefault("warnings", []).append(
                "--contrastive requested without --baseline; skipping contrastive section."
            )
        else:
            baseline_path = Path(args.baseline)
            try:
                baseline_markdown = baseline_path.read_text(encoding="utf-8")
                baseline_metrics, baseline_warnings = extract_baseline_json(
                    baseline_markdown
                )
                result.setdefault("meta", {}).setdefault("warnings", []).extend(
                    baseline_warnings
                )
            except OSError as exc:
                baseline_metrics = None
                result.setdefault("meta", {}).setdefault("warnings", []).append(
                    f"Failed to read baseline file {baseline_path}: {exc}"
                )
            if baseline_metrics is None:
                result.setdefault("meta", {}).setdefault("warnings", []).append(
                    "No baseline JSON code block found in --baseline markdown; skipping contrastive section."
                )
            elif args.aggregate:
                result["contrastive"] = compute_contrastive(
                    result["computationalMetrics"], baseline_metrics
                )

    _emit(result, args.output)
    return 0


def _emit(result: dict, output_path: Optional[str]) -> None:
    payload = json.dumps(result, ensure_ascii=False, indent=2)
    if output_path:
        Path(output_path).write_text(payload, encoding="utf-8")
    else:
        print(payload)


if __name__ == "__main__":
    sys.exit(main())
